import type { BusinessCalendar } from './business-calendar-model';
import type { Workspace } from './workspace-model';

export const BusinessHolidayStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type BusinessHolidayStatusKey = keyof typeof BusinessHolidayStatusKeyToLabel;

export interface BusinessHoliday {
  /**
   * @displayName Business Holiday ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  name1: string;
  /**
   * @displayName Business Calendar
   * @validationRule Required for create/update operations
   */
  businessCalendar: Pick<BusinessCalendar, 'id' | 'name1'>;
  /**
   * @displayName Holiday Date
   * @validationRule Required for create/update operations
   */
  holidayDate: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: BusinessHolidayStatusKey;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _BusinessHoliday = 'BusinessHoliday' as const;